<?php use App\Models\Ticket; ?>
<?php if(isset($_SESSION['new_form_link'])): $newLink=$_SESSION['new_form_link']; unset($_SESSION['new_form_link']); ?><div class="notice success"><div><strong>Votre lien de collecte est prêt</strong><p>Conservez-le maintenant : il ne sera pas affiché à nouveau.</p><a href="<?= e($newLink['url']) ?>" target="_blank" rel="noopener"><?= e($newLink['url']) ?></a></div><button class="button subtle" data-copy="<?= e($newLink['url']) ?>"><?= icon('link') ?>Copier</button></div><?php endif; ?>
<div class="feature-banner"><span class="feature-orb"><?= icon('form') ?></span><div><span class="eyebrow">UNE PORTE OUVERTE AUX BONNES IDÉES</span><h2>Une demande. Un lien. C’est tout.</h2><p>Vos interlocuteurs décrivent leur besoin sans créer de compte.<br>Vous retrouvez un ticket prêt à être pris en charge.</p></div><?php if($user['role']==='admin'): ?><button class="button primary" data-open="new-form-dialog"><?= icon('plus') ?>Créer un formulaire</button><?php endif; ?></div>
<div class="form-cards"><?php foreach($forms as $form): ?><article class="panel form-card"><div class="panel-header"><span class="kpi-symbol lavender"><?= icon('form') ?></span><span class="pill <?= $form['enabled']?'success':'neutral' ?>"><?= $form['enabled']?'Collecte ouverte':'Désactivé' ?></span></div><h2><?= e($form['title']) ?></h2><p><?= e($form['description']) ?></p><div class="form-meta"><span><?= e(Ticket::TYPES[$form['ticket_type']]) ?></span><span><?= count(json_decode($form['fields_json'],true)) ?> champs</span></div><?php if($user['role']==='admin'): ?><div class="form-actions"><button class="button subtle" data-open="edit-form-<?= (int)$form['id'] ?>">Personnaliser</button><details class="dropdown align-right"><summary class="icon-button" aria-label="Actions du formulaire"><?= icon('more') ?></summary><div class="dropdown-menu"><form action="/forms/<?= (int)$form['id'] ?>/toggle" method="post"><?= csrf() ?><button><?= $form['enabled']?'Désactiver':'Réactiver' ?> le formulaire</button></form><form action="/forms/<?= (int)$form['id'] ?>/rotate" method="post"><?= csrf() ?><button data-confirm="Créer un nouveau lien ? Le précédent cessera de fonctionner.">Générer un nouveau lien</button></form></div></details></div><?php endif; ?></article><?php endforeach; if(!$forms): ?><div class="panel empty-state"><span class="kpi-symbol lavender"><?= icon('form') ?></span><h3>Accueillez le prochain besoin.</h3><p>Commencez avec un formulaire simple : demande de fonctionnalité,<br>rapport de bug, incident ou demande de changement.</p></div><?php endif; ?></div>
<?php if($user['role']==='admin'): $formVariants=[null,...$forms]; foreach($formVariants as $editForm): $fFields=$editForm?json_decode($editForm['fields_json'],true):[['key'=>'title','label'=>'Résumé','required'=>true],['key'=>'description','label'=>'Description','required'=>true],['key'=>'priority','label'=>'Priorité','required'=>false]]; $indexed=array_column($fFields,null,'key'); ?><dialog id="<?= $editForm?'edit-form-'.$editForm['id']:'new-form-dialog' ?>" class="dialog"><form method="post" action="/forms" class="stack"><?= csrf() ?><input type="hidden" name="project_id" value="<?= (int)$project['id'] ?>"><input type="hidden" name="id" value="<?= (int)($editForm['id']??0) ?>"><input type="hidden" name="_return" value="/forms"><header class="dialog-header"><div><span class="eyebrow">COLLECTER SANS COMPLIQUER</span><h2><?= $editForm?'Personnaliser le formulaire':'Créer un formulaire' ?></h2></div><button type="button" class="icon-button" data-close aria-label="Fermer"><?= icon('close') ?></button></header><label>Titre<input name="title" value="<?= e($editForm['title']??'Une nouvelle demande') ?>" maxlength="160" required></label><label>Message d’accueil<textarea name="description" rows="2"><?= e($editForm['description']??'Décrivez votre besoin. Notre équipe vous répondra rapidement.') ?></textarea></label><label>Type de ticket créé<select name="ticket_type"><?php foreach(Ticket::TYPES as $k=>$v): if($k==='subtask') continue; ?><option value="<?= e($k) ?>" <?= ($editForm['ticket_type']??'task')===$k?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select></label><div class="field-builder"><h3>Vos champs</h3><p class="help-text">L’adresse e-mail du demandeur est toujours requise. Les champs internes du projet ne sont jamais exposés.</p><?php foreach(App\Controllers\FormController::FIELDS as $key=>$label): $f=$indexed[$key]??null; ?><div class="builder-field"><label class="check-label"><input type="checkbox" name="fields[]" value="<?= e($key) ?>" <?= $f?'checked':'' ?> <?= $key==='title'?'disabled':'' ?>><?= e($label) ?></label><label>Libellé<input name="labels[<?= e($key) ?>]" value="<?= e($f['label']??$label) ?>" maxlength="120"></label><label class="check-label"><input type="checkbox" name="required[]" value="<?= e($key) ?>" <?= !empty($f['required'])?'checked':'' ?> <?= $key==='title'?'disabled':'' ?>>Obligatoire</label><?php if($key!=='title'&&$key!=='priority'): ?><details><summary>Condition d’affichage</summary><div class="inline-fields"><label>Afficher si<select name="condition_field[<?= e($key) ?>]"><option value="">Toujours</option><option value="priority" <?= !empty($f['condition'])?'selected':'' ?>>Priorité égale à</option></select></label><label>Valeur<select name="condition_value[<?= e($key) ?>]"><?php foreach(Ticket::PRIORITIES as $v=>$l): ?><option value="<?= e($v) ?>" <?= ($f['condition']['value']??'high')===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></label></div></details><?php endif; ?></div><?php endforeach; ?></div><p class="help-text"><?= icon('lock') ?>Le lien permet à toute personne qui le possède de soumettre une demande. Il ne donne aucun accès aux tickets ou aux utilisateurs.</p><button class="button primary"><?= $editForm?'Enregistrer les changements':'Créer et obtenir le lien' ?></button></form></dialog><?php endforeach; endif; ?>
